  throw new Error('No valid SQL statements generated on Retry 2. Rejected: ' + JSON.stringify(rejected));
}

return validated.map(sql => ({ json: { sql } }));

// Normalize all paths into the same response shape
const input = $input.first().json;

// Path A: came from success (If false branch) — already has all_results
// Path B: came from Aggregate1/2 — has raw results array
let results, attempt;

if (input.all_results) {
  // Direct pass from Check Attempt node
  results = input.all_results;
  attempt = input.attempt;
} else if (input.results) {
  // Raw aggregate output
  const raw = input.results || [];
  results = raw.flatMap(r => Array.isArray(r.results) ? r.results : [r]);
  attempt = 'final';
} else {
  results = [];
  attempt = 'unknown';
}

const failed  = results.filter(r => r.success === false);
const success = results.filter(r => r.success === true);

return [{
  json: {
    attempt,
    success_count: success.length,
    fail_count:    failed.length,
    has_failures:  failed.length > 0,
    failed_stmts:  failed.map(r => ({ sql: r.sql, error: r.error })),
    all_results:   results,
  }
}];
